input.command:
GC=$(git rev-parse --git-common-dir) && GC=$(cd "$GC" && pwd) && mkdir -p "$GC/gsd-path/model-selection" && cat > "$GC/gsd-path/capabilities.json" <<'EOF'
{
  "host": "claude-code",
  "model": {"field": "model", "values": ["sonnet", "opus", "haiku", "fable"]}
}
EOF
echo "$GC/gsd-path/capabilities.json"; cat "$GC/gsd-path/capabilities.json"
